dashboard.definition:
{
  "title": "Agentic Attack Activity",
  "description": "",
  "inputs": {
    "time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-30d@d,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "bg_artex": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1A1C20",
        "strokeColor": "#2A2E35",
        "rx": 8
      }
    },
    "bar_artex": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#4C8DF6",
        "strokeColor": "#4C8DF6"
      }
    },
    "dot_artex": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#4C8DF6",
        "strokeColor": "#4C8DF6",
        "rx": 2
      }
    },
    "name_artex": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "**ARTEX**",
        "fontColor": "#E8EAED",
        "fontSize": "large"
      }
    },
    "desc_artex": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Go planner and worker agents with a web console. AntiFox is the same code renamed.",
        "fontColor": "#9AA0A6",
        "fontSize": "small"
      }
    },
    "big_artex": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "t_artex"
      },
      "options": {
        "majorValue": "> primary | seriesByName('sources') | lastPoint()",
        "sparklineValues": "> primary | seriesByName('hits')",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#4C8DF6",
        "sparklineAreaColor": "#4C8DF6",
        "majorColor": "#E8EAED",
        "underLabel": "hosts and addresses",
        "underLabelFontSize": 12,
        "backgroundColor": "#1A1C20",
        "majorFontSize": 40
      }
    },
    "rule_artex": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#2A2E35",
        "strokeColor": "#2A2E35"
      }
    },
    "hits_artex": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "t_artex"
      },
      "options": {
        "majorValue": "> primary | seriesByName('total_hits') | lastPoint()",
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "majorColor": "#E8EAED",
        "majorFontSize": 18,
        "backgroundColor": "#1A1C20",
        "underLabel": "results",
        "underLabelFontSize": 12
      }
    },
    "new_artex": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "a_artex"
      },
      "options": {
        "majorValue": "> primary | seriesByName('new') | lastPoint()",
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "majorColor": "#E8EAED",
        "majorFontSize": 18,
        "backgroundColor": "#1A1C20",
        "underLabel": "new, 7 days",
        "underLabelFontSize": 12
      }
    },
    "all_artex": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "a_artex"
      },
      "options": {
        "majorValue": "> primary | seriesByName('all_time') | lastPoint()",
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "majorColor": "#E8EAED",
        "majorFontSize": 18,
        "backgroundColor": "#1A1C20",
        "underLabel": "all time",
        "underLabelFontSize": 12
      }
    },
    "port_artex": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "**8787**  \nconsole port",
        "fontColor": "#9AA0A6",
        "fontSize": "small"
      }
